{"implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])

    node_map = {n['id']: n for n in nodes}
    parent_map = {n['id']: n['parent'] for n in nodes}

    must_retain = set()

    def retain_with_ancestors(nid):
        while nid is not None:
            if nid in must_retain:
                break
            must_retain.add(nid)
            nid = parent_map.get(nid)

    # Always retain non-removable nodes and all their ancestors
    for n in nodes:
        if not n['removable']:
            retain_with_ancestors(n['id'])

    # Determine which required symbols are already covered by must_retain
    covered_symbols = {node_map[nid]['symbol'] for nid in must_retain}

    # For required symbols not yet covered, pick the removable node with
    # highest utility and retain it along with its ancestors
    needed_symbols = required_symbols - covered_symbols
    for sym in needed_symbols:
        candidates = [n for n in nodes if n['symbol'] == sym and n['removable']]
        if candidates:
            best = max(candidates, key=lambda n: n['utility'])
            retain_with_ancestors(best['id'])

    retained = []
    removed = []
    for n in nodes:
        if n['id'] in must_retain:
            retained.append(n['id'])
        else:
            removed.append(n['id'])

    return {
        'retained_node_ids': retained,
        'removed_node_ids': removed
    }
